for cid, obj in P.items():
    obj2 = {"case_id": cid, "prediction_text": obj["prediction_text"], "basis": obj["basis"],
            "confidence": obj["confidence"], "trigger": obj["trigger"]}
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(obj2, f, ensure_ascii=False, indent=1)

# self-verify: open each B15 file exactly by id list (no directory listing)
ids = ["LY-%d" % i for i in range(517, 537)]
ok = 0
for cid in ids:
    with open(os.path.join(OUT, cid + ".json"), encoding="utf-8") as f:
        d = json.load(f)
    assert d["case_id"] == cid and set(d) == {"case_id","prediction_text","basis","confidence","trigger"}
    assert isinstance(d["confidence"], float) and 0 <= d["confidence"] <= 1
    tr = d["trigger"]
    assert set(tr) == {"changed_main","reserve_used","disputed","reason"} and all(isinstance(tr[k], bool) for k in ("changed_main","reserve_used","disputed"))
    assert d["basis"].splitlines()[0] == "liuyao"
    ok += 1
print("written_and_verified:", ok)
print("changed_main:", sum(1 for i in ids if P[i]["trigger"]["changed_main"]))
print("reserve_used:", sum(1 for i in ids if P[i]["trigger"]["reserve_used"]))
print("disputed:", sum(1 for i in ids if P[i]["trigger"]["disputed"]))
